import {object, string, optionalString, optionalNumber, array, optionalBoolean, number} from '../shared/wire';
import type {Item} from './types';
export function readItem(value: unknown): Item {const v=object(value), tags = v.ImageTags == null ? {} : object(v.ImageTags), user = v.UserData == null ? {} : object(v.UserData); return {
 Id: string(v.Id), Name: string(v.Name), Type: optionalString(v.Type), SeriesId: optionalString(v.SeriesId), SeriesPrimaryImageTag: optionalString(v.SeriesPrimaryImageTag), ImageTags: {Primary: optionalString(tags.Primary)},
 Genres: v.Genres == null ? undefined : array(v.Genres, string), Overview: optionalString(v.Overview), ChildCount: optionalNumber(v.ChildCount), RunTimeTicks: optionalNumber(v.RunTimeTicks), ProductionYear: optionalNumber(v.ProductionYear), CommunityRating: optionalNumber(v.CommunityRating), IndexNumber: optionalNumber(v.IndexNumber), UserData: {UnplayedItemCount: optionalNumber(user.UnplayedItemCount)}};}
export function readItems(value: unknown): Item[] {return array(object(value).Items, readItem);}
export function readAdmin(value: unknown): boolean {return optionalBoolean(object(object(value).Policy).IsAdministrator) === true;}
export function readEvents(value: unknown) {const v = object(value); return {users: array(v.users,string), events: array(v.events, value => {const e=object(value); const ts=string(e.ts); if (!Number.isFinite(Date.parse(ts))) throw Error('Invalid event timestamp'); return {ts, user:string(e.user), action:optionalString(e.action), type:string(e.type), undoOf:optionalString(e.undoOf), ok:optionalBoolean(e.ok), itemId:optionalString(e.itemId), itemName:optionalString(e.itemName), kind:optionalString(e.kind), seasons:e.seasons == null ? undefined : array(e.seasons,string)};})};}
export function readSummary(value: unknown) {const v=object(value); const top=(value:unknown)=>array(value,value=>{const t=object(value); return {itemId:string(t.itemId),name:optionalString(t.name),count:number(t.count),users:array(t.users,string)};}); return {users:array(v.users,value=>{const u=object(value); return {user:string(u.user),watched:number(u.watched),dismiss:number(u.dismiss),watchlist:number(u.watchlist),lastSeen:optionalString(u.lastSeen)};}), topWatched:top(v.topWatched),topDismissed:top(v.topDismissed),topWatchlisted:top(v.topWatchlisted)};}
